       "id": "m04-l04-p03-b10",
       "type": "code",
       "language": "csharp",
       "dir": "ltr",
       "code": "public static bool IsPalindrome(string str)\n{\n    Stack<char> stk = new Stack<char>();\n    for (int i = 0; i < str.Length; i++)\n        stk.Push(str[i]);\n    string strRev = \" \";\n    while (!stk.IsEmpty())\n        strRev += stk.Pop();\n    return str.Equals(strRev);\n}",
       "origin": "book"
