       "code": "public static Stack<int> Watermelon(Stack<int> st)\n{\n    Stack<int> res = new Stack<int>();\n    while (!st.IsEmpty())\n    {\n        int x = st.Pop();\n        while (!res.IsEmpty() && res.Top() > x)\n            st.Push(res.Pop());\n        res.Push(x);\n    }\n    return res;\n}",
