       "dir": "ltr",
       "code": "public static Stack<Student> Passed(Stack<Student> st)\n{\n    Stack<Student> temp = new Stack<Student>();\n    Stack<Student> res = new Stack<Student>();\n    while (!st.IsEmpty())\n        temp.Push(st.Pop());\n    while (!temp.IsEmpty())\n    {\n        Student s = temp.Pop();\n        st.Push(s);\n        if (s.GetGrade() >= 55)\n            res.Push(s);\n    }\n    return res;\n}",
